import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { getUser } from '../../utils/auth';

const Sidebar = ({ onClose }) => {
  const location = useLocation();
  const user = getUser();
  const [stats, setStats] = useState({
    totalBookings: 0,
    activeBookings: 0,
    pendingApprovals: 0,
    upcomingBookings: 0
  });

  useEffect(() => {
    // Simulasi load stats
    setTimeout(() => {
      setStats({
        totalBookings: Math.floor(Math.random() * 50) + 10,
        activeBookings: Math.floor(Math.random() * 10) + 2,
        pendingApprovals: Math.floor(Math.random() * 5),
        upcomingBookings: Math.floor(Math.random() * 8) + 1
      });
    }, 1000);
  }, []);

  const isActive = (path) => location.pathname === path;

  // Menu sesuai role
  const menuByRole = {
    admin: [
      {
        name: 'Admin Dashboard',
        path: '/admin/dashboard',
        icon: '👑',
        description: 'System overview'
      },
      {
        name: 'Kelola Booking',
        path: '/admin/bookings',
        icon: '📊',
        description: 'Manage all bookings',
        badge: stats.pendingApprovals > 0 ? stats.pendingApprovals : null
      },
      {
        name: 'Kelola Ruangan',
        path: '/admin/rooms',
        icon: '🏢',
        description: 'Room management'
      },
      {
        name: 'Kelola Users',
        path: '/admin/users',
        icon: '👥',
        description: 'User management'
      },
      {
        name: 'Zoom Settings',
        path: '/admin/zoom',
        icon: '💻',
        description: 'Zoom configuration'
      }
    ],
    zoom_approver: [
      {
        name: 'Zoom Dashboard',
        path: '/zoom/dashboard',
        icon: '💻',
        description: 'Zoom overview'
      },
      {
        name: 'Zoom Requests',
        path: '/zoom/requests',
        icon: '📝',
        description: 'Pending approvals',
        badge: stats.pendingApprovals > 0 ? stats.pendingApprovals : null
      }
    ],
    room_approver: [
      {
        name: 'Room Dashboard',
        path: '/room/dashboard',
        icon: '🏢',
        description: 'Room overview'
      },
      {
        name: 'Room Requests',
        path: '/room/requests',
        icon: '📝',
        description: 'Pending approvals',
        badge: stats.pendingApprovals > 0 ? stats.pendingApprovals : null
      },
      {
        name: 'Kelola Ruangan',
        path: '/logistik/rooms',
        icon: '🏢',
        description: 'Manage facilities'
      }
    ],
    user: [
      {
        name: 'Dashboard',
        path: '/user/dashboard',
        icon: '🏠',
        description: 'Overview & Analytics'
      },
      {
        name: 'Buat Booking',
        path: '/user/booking',
        icon: '➕',
        description: 'Buat reservasi baru',
        badge: 'New'
      },
      {
        name: 'Booking Saya',
        path: '/user/mybookings',
        icon: '📋',
        description: 'Kelola booking Anda',
        badge: stats.activeBookings > 0 ? stats.activeBookings : null
      }
    ]
  };

  // Info role
  const roleInfo = {
    admin: { label: 'Administrator', icon: '👑', color: 'purple' },
    zoom_approver: { label: 'Zoom Approver', icon: '💻', color: 'blue' },
    room_approver: { label: 'Room Approver', icon: '🏢', color: 'green' },
    user: { label: 'User', icon: '👤', color: 'gray' }
  }[user?.role] || { label: 'User', icon: '👤', color: 'gray' };

  const getDisplayName = () => {
    if (user?.name) return user.name;
    if (user?.email) return user.email.split('@')[0];
    return 'User';
  };

  return (
    <div className="hidden lg:block w-72 bg-white shadow-xl border-r border-gray-200 flex flex-col z-40">
      {/* Header */}
      <div className="bg-gradient-to-br from-blue-600 via-blue-700 to-indigo-800 p-4 text-white">
        <div className="flex items-center space-x-3 mb-3">
          <div className="w-12 h-12 bg-white bg-opacity-20 rounded-xl flex items-center justify-center">
            <span className="text-2xl">{roleInfo.icon}</span>
          </div>
          <div>
            <h2 className="text-base font-bold truncate">{getDisplayName()}</h2>
            <p className="text-xs opacity-90 truncate">{user?.email}</p>
          </div>
        </div>
        <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium bg-white bg-opacity-20">
          {roleInfo.icon} {roleInfo.label}
        </span>
      </div>

      {/* Stats */}
      <div className="p-3 bg-gradient-to-br from-gray-50 via-blue-50 to-indigo-50 border-b border-gray-100">
        <div className="grid grid-cols-2 gap-2">
          <div className="bg-white p-3 rounded-xl shadow-md border border-gray-100">
            <div className="flex items-center space-x-2">
              <span className="text-blue-600 text-lg">📊</span>
              <div>
                <div className="text-lg font-bold text-blue-600">{stats.totalBookings}</div>
                <div className="text-xs text-gray-500 font-medium">Total</div>
              </div>
            </div>
          </div>
          <div className="bg-white p-3 rounded-xl shadow-md border border-gray-100">
            <div className="flex items-center space-x-2">
              <span className="text-green-600 text-lg">✅</span>
              <div>
                <div className="text-lg font-bold text-green-600">{stats.activeBookings}</div>
                <div className="text-xs text-gray-500 font-medium">Active</div>
              </div>
            </div>
          </div>
        </div>
        {stats.upcomingBookings > 0 && (
          <div className="mt-3 p-3 bg-gradient-to-r from-blue-100 to-cyan-100 border border-blue-200 rounded-xl shadow-sm">
            <div className="flex items-center space-x-2">
              <span className="text-lg">⏰</span>
              <div>
                <span className="text-sm text-blue-800 font-semibold">
                  {stats.upcomingBookings} upcoming booking{stats.upcomingBookings > 1 ? 's' : ''}
                </span>
                <p className="text-xs text-blue-600">Starting soon</p>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Menu */}
      <div className="flex-1 overflow-y-auto bg-gradient-to-b from-gray-50 to-white">
        <nav className="p-3 space-y-1">
          {menuByRole[user?.role]?.map((item) => (
            <Link
              key={item.path}
              to={item.path}
              onClick={onClose}
              className={`
                flex items-center space-x-3 p-3 rounded-xl transition-all duration-300 relative
                ${isActive(item.path)
                  ? 'bg-white shadow-md border-l-4 border-blue-500 scale-[1.01]'
                  : 'text-gray-700 hover:bg-white hover:shadow-sm hover:-translate-y-0.5'
                }
              `}
            >
              <span className="w-10 h-10 flex items-center justify-center text-lg">{item.icon}</span>
              <div className="min-w-0 flex-1">
                <div className="font-semibold text-sm">{item.name}</div>
                <div className="text-xs text-gray-500">{item.description}</div>
              </div>
              {item.badge && (
                <span className="ml-2 px-2 py-0.5 rounded-full bg-blue-500 text-white text-xs font-bold">
                  {typeof item.badge === 'number' && item.badge > 99 ? '99+' : item.badge}
                </span>
              )}
            </Link>
          ))}
        </nav>
      </div>

      {/* Footer */}
      <div className="p-6 border-t border-gray-200 bg-gray-50">
        <div className="text-center">
          <div className="flex items-center justify-center space-x-2 mb-2">
            <div className="w-6 h-6 bg-gradient-to-r from-blue-600 to-purple-600 rounded-lg flex items-center justify-center shadow-md">
              <span className="text-white text-xs font-bold">B</span>
            </div>
            <span className="text-sm font-bold text-gray-800">BRIRoom</span>
            <span className="px-2 py-1 bg-green-500 text-white text-xs font-bold rounded-full">v2.1</span>
          </div>
          <div className="text-xs text-gray-600 font-medium">
            Modern Room Management
          </div>
          <div className="text-xs text-gray-400 mt-1">
            © 2025 Bank BRI
          </div>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;
